import { useShakeable } from "@/core/hooks";
import styles from "./bottom-action-buttons.module.less";
import { motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";
import { PropsWithChildren, useEffect } from "react";
import {
  ButtonProps,
  PrimaryButton,
  PrimaryButtonLink,
  SecondaryButton,
  SecondaryButtonLink,
  GhostButton,
  GhostButtonLink,
  OutlineButton,
  OutlineButtonLink,
  ButtonLinkProps,
} from "@/core/components/primitives/parks-button/parks-button";

type ActionButton =
  | (ButtonProps & { buttonType: "PrimaryButton" | "SecondaryButton" | "GhostButton" | "OutlineButton" })
  | (ButtonLinkProps & {
      buttonType: "PrimaryButtonLink" | "SecondaryButtonLink" | "GhostButtonLink" | "OutlineButtonLink";
    });

export type BottomActionButtonsProps = {
  /** Button type and props for the first button */
  firstButton: ActionButton;
  /** Button type and props for the second button */
  secondButton?: ActionButton;
  /** Layout direction of the buttons */
  direction?: "horizontal" | "vertical";
  /** Which button should shake, if any */
  shakeButton?: "first" | "second";
  /** Optional text above the buttons */
  text?: string;
  /** Additional class name for the wrapper */
  className?: string;
};

const Button = ({ button, shakeButton }: { button: ActionButton; shakeButton?: boolean }) => {
  const { buttonType, ...buttonProps } = button;

  const allComponents = {
    PrimaryButton,
    PrimaryButtonLink,
    SecondaryButton,
    SecondaryButtonLink,
    GhostButton,
    GhostButtonLink,
    OutlineButton,
    OutlineButtonLink,
  } as const;

  const ButtonComponent = allComponents[buttonType] as React.ComponentType<typeof buttonProps>;

  const [Shakeable, shake] = useShakeable({
    rotationDegrees: 4,
    shakesPerRepeat: 4,
    durationPerRepeat: 400,
    repeat: 2,
    repeatDelay: 1750,
  });

  useEffect(() => {
    if (shakeButton) {
      shake();
    }
  }, [shakeButton, shake]);

  return (
    <Shakeable wrapperClassName={styles.buttonWrapper}>
      <ButtonComponent {...buttonProps} />
    </Shakeable>
  );
};

/**
 * Component with one or two buttons that are sticky to the bottom (above footer)
 */
const BottomActionButtons = ({
  firstButton,
  secondButton,
  direction,
  shakeButton,
  children,
  className,
}: PropsWithChildren<BottomActionButtonsProps>) => {
  return (
    <motion.div className={multipleClassNames(styles.wrapper, className)}>
      {children && <div className={styles.children}>{children}</div>}
      <div className={multipleClassNames(styles.actionButtonWrapper, direction === "vertical" && styles.vertical)}>
        <Button button={firstButton} shakeButton={shakeButton === "first"} />
        {secondButton && <Button button={secondButton} shakeButton={shakeButton === "second"} />}
      </div>
    </motion.div>
  );
};

BottomActionButtons.displayName = "BottomActionButtons";

export default BottomActionButtons;
