import { Meta, StoryObj } from "@storybook/react";
import BottomActionButtons from "./bottom-action-buttons";
import { useState } from "react";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";
import { action } from "storybook/actions";

type ButtonTypeOption =
  | "PrimaryButton"
  | "SecondaryButton"
  | "GhostButton"
  | "OutlineButton"
  | "PrimaryButtonLink"
  | "SecondaryButtonLink"
  | "GhostButtonLink"
  | "OutlineButtonLink";

type StoryArgs = React.ComponentProps<typeof BottomActionButtons> & {
  firstButtonType?: ButtonTypeOption;
  secondButtonType?: ButtonTypeOption;
  showExtraContent?: boolean;
};

const meta: Meta<StoryArgs> = {
  title: "Primitives/Bottom Action Buttons",
  component: BottomActionButtons,
  render: function StoryComponent({ firstButtonType, secondButtonType, ...args }) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const firstButton = args.firstButton!;
    const showExtraContent = args.showExtraContent === true;
    const [firstButtonClickCounter, setFirstButtonClickCounter] = useState(0);
    const [secondButtonClickCounter, setSecondButtonClickCounter] = useState(0);
    return (
      <ContentContainer>
        <div style={{ width: "100%" }}>
          {showExtraContent && (
            <div
              style={{
                height: "3rem",
                width: "100%",
                background: "var(--foundation-color-primary-600)",
                color: "var(--foundation-color-primary-100)",
                textAlign: "center",
              }}
            >
              Header
            </div>
          )}
          <h2 style={{ marginTop: "0" }}>Much content</h2>
          <p>Such wow!</p>
          <p className="story-theme-name" style={{ paddingTop: "1rem" }}>
            First button clicks: {firstButtonClickCounter}
          </p>
          <p className="story-theme-name">Second button clicks: {secondButtonClickCounter}</p>
          {showExtraContent && (
            <div style={{ height: "110vh", backgroundColor: "var(--foundation-color-secondary-500)" }}>
              <p>Loads of content</p>
              <p>Make buttons sticky</p>
              <p>Woooooow</p>
              {[...Array(6)].map((_, i) => (
                <div
                  key={i}
                  style={{
                    background: "var(--foundation-color-secondary-200)",
                    height: "100px",
                    borderBottom: "1px solid black",
                    textAlign: "center",
                  }}
                >
                  Block {i}
                </div>
              ))}
            </div>
          )}
        </div>
        <BottomActionButtons
          {...args}
          firstButton={{
            ...firstButton,
            buttonType: firstButtonType ?? firstButton.buttonType,
            onClick: () => {
              setFirstButtonClickCounter((c) => c + 1);
            },
          }}
          secondButton={
            args.secondButton
              ? {
                  ...args.secondButton,
                  buttonType: secondButtonType ?? args.secondButton.buttonType,
                  onClick: () => {
                    setSecondButtonClickCounter((c) => c + 1);
                  },
                }
              : undefined
          }
        />
        {showExtraContent && (
          <div
            style={{
              height: "3rem",
              width: "100%",
              background: "var(--foundation-color-primary-600)",
              color: "var(--foundation-color-primary-100)",
              textAlign: "center",
            }}
          >
            Footer
          </div>
        )}
      </ContentContainer>
    );
  },
  argTypes: {
    showExtraContent: {
      control: { type: "boolean" },
    },
    firstButtonType: {
      options: [
        "PrimaryButton",
        "SecondaryButton",
        "GhostButton",
        "OutlineButton",
        "PrimaryButtonLink",
        "SecondaryButtonLink",
        "GhostButtonLink",
        "OutlineButtonLink",
      ],
      control: { type: "select" },
    },
    secondButtonType: {
      options: [
        "PrimaryButton",
        "SecondaryButton",
        "GhostButton",
        "OutlineButton",
        "PrimaryButtonLink",
        "SecondaryButtonLink",
        "GhostButtonLink",
        "OutlineButtonLink",
      ],
      control: { type: "select" },
    },
    shakeButton: {
      options: ["first", "second", undefined],
      control: { type: "radio" },
    },
  },
};

export default meta;

type Story = StoryObj<StoryArgs>;

export const Default: Story = {
  args: {
    firstButtonType: "PrimaryButton",
    firstButton: {
      buttonType: "PrimaryButton",
      label: "First Button",
      onClick: action("First button clicked"),
    },

    direction: "horizontal",
    shakeButton: undefined,
    showExtraContent: false,
  },
};

export const FullWidth: Story = {
  args: {
    ...Default.args,
    firstButton: Default.args?.firstButton ? { ...Default.args.firstButton, isFullWidth: true } : undefined,
  },
};

export const TwoButtons: Story = {
  args: {
    ...Default.args,
    secondButton: {
      buttonType: "SecondaryButton",
      label: "Second Button",
      onClick: action("Second button clicked"),
    },
  },
};

export const TwoButtonsFullWidth: Story = {
  args: {
    ...TwoButtons.args,
    firstButton: TwoButtons.args?.firstButton ? { ...TwoButtons.args.firstButton, isFullWidth: true } : undefined,
    secondButton: TwoButtons.args?.secondButton
      ? {
          ...TwoButtons.args.secondButton,
          isFullWidth: true,
        }
      : undefined,
  },
};

export const Vertical: Story = {
  args: {
    ...TwoButtons.args,
    direction: "vertical",
  },
};

export const VerticalFullWidth: Story = {
  args: {
    ...Vertical.args,
    firstButton: Vertical.args?.firstButton ? { ...Vertical.args.firstButton, isFullWidth: true } : undefined,
    secondButton: Vertical.args?.secondButton
      ? {
          ...Vertical.args.secondButton,
          isFullWidth: true,
        }
      : undefined,
  },
};

export const ShakeFirstButton: Story = {
  args: {
    ...TwoButtons.args,
    shakeButton: "first",
  },
};

export const ShakeSecondButton: Story = {
  args: {
    ...TwoButtons.args,
    shakeButton: "second",
  },
};

export const MuchContent: Story = {
  args: {
    ...TwoButtonsFullWidth.args,
    showExtraContent: true,
  },
};
